function chips(s){const n=condition(s,'noise'),c=condition(s,'crowd');return `<div class="chips"><span class="chip ${['good','medium','high'][crowds.indexOf(c)]}">${icon('people',13)}${c}</span><span class="chip noise">${icon(n==='Quiet'?'quiet':'volume',13)}${n}</span></div>`}
