function render(){if(!campus)return;const cmp=page==='compare',saved=page==='saved';$('#hero').hidden=page!=='explore';$('#collectionHero').hidden=page==='explore';$('#collectionHero').innerHTML=page==='explore'?'':`<div class="kicker"><span class="kicker-line"></span>YOUR CAMPUS GUIDE</div><h1>${saved?'Saved spots':'Compare spots'}</h1><p>${saved?'Study spaces you’ve bookmarked on this device.':'Choose up to three spaces to compare side by side.'}</p>`;$('#filters').hidden=cmp;$('#filterSummary').hidden=cmp;$('#resultsArea').hidden=cmp;$('#comparison').hidden=!cmp;$$('[data-nav]').forEach(a=>{a.classList.toggle('active',a.dataset.nav===page);if(a.dataset.nav===page)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});$('#saveCount').textContent=state.saved.length||'';$('#cmpCount').textContent=state.compare.length||'';document.title=(cmp?'Compare spots':saved?'Saved spots':'Campus explorer')+' · StudySpot';
if(cmp){renderCompare();return}
quickFilters();const list=filtered(),f=state.filters;const n=[f.type,f.noise,f.crowd,f.building,f.open,...f.features].filter(Boolean).length;$('#filterCount').textContent=n||'';const terms=[f.q&&'“'+f.q+'”',f.type,f.building,f.noise,f.crowd,f.open&&'Open now',...f.features].filter(Boolean);$('#filterSummary').innerHTML=terms.length?`<div class="summary"><span>Showing: ${terms.map(esc).join(' · ')}</span>${btn('clear','Clear filters','','textbtn')}</div>`:'';$('#resultTitle').innerHTML=(saved?'Your spots':'Explore spots')+` <span class="count">${list.length} ${list.length===1?'spot':'spots'}</span>`;$('#eyebrow').textContent=saved?'BOOKMARKS':'SPOT DIRECTORY · TUE 2 PM DEMO';
const mobile=matchMedia('(max-width:700px)').matches,v=state.view==='split'&&mobile?'list':state.view;$('#views').innerHTML=[['split','Split view'],['list','List view'],['map','Map view']].map(([mode,label])=>`<button data-view="${mode}" title="${label}" aria-label="${label}" aria-pressed="${mode===v}">${icon(mode,15)}${mode===v?`<span>${label.split(' ')[0]}</span>`:''}</button>`).join('');$('#layout').className='layout '+(v==='list'?'list-only':v==='map'?'map-only':'');$('#cards').hidden=v==='map'&&list.length>0;$('#mapPanel').hidden=v==='list'||!list.length;$('#cards').innerHTML=list.length?list.map(spotCard).join(''):saved&&!state.saved.length?empty('Your saved shelf is empty','Use the bookmark on any spot to keep it here.','explore','Explore spots','bookmark'):empty('No spots match just yet','Try another building, or clear your filters to see more spaces.','clear','Clear filters');if(!$('#mapPanel').hidden)renderMap(list);say(list.length+' spots found')}
function renderMap(list){if(!list.some(s=>s.id===selectedPin))selectedPin='';const p=find(selectedPin);$('#mapPanel').innerHTML=`<div class="mapcard"><div class="maphead"><strong>${icon('map',18)}Campus map</strong><small>Sample campus</small></div><div class="mapstage" tabindex="0" role="group" aria-label="Campus map. Select pins for details. When zoomed, drag or use arrow keys to pan."><div class="maplayer"><span class="origin" title="Campus Gate · walking origin"></span>${list.map(s=>`<button class="mappin ${s.id===selectedPin?'selected':''}" data-pin="${s.id}" aria-label="Locate ${s.name}" aria-pressed="${s.id===selectedPin}" style="left:${s.pos[0]}%;top:${s.pos[1]}%;${color(s)}"><span class="pinhead">${icon(types[s.type][0],16)}</span>${s.label?`<span class="pinlabel">${s.label}</span>`:''}</button>`).join('')}</div><span class="north" aria-hidden="true">N<i></i></span><div class="mapcontrol">${btn('zoom-in','','plus','',`aria-label="Zoom in" ${zoom>=2?'disabled':''}`)}${btn('zoom-out','','minus','',`aria-label="Zoom out" ${zoom<=1?'disabled':''}`)}</div>${btn('reset-map','','locate','recenter','aria-label="Reset map view" title="Reset map view"')}${p?`<div class="map-popup"><div><strong>${p.name}</strong><small>${condition(p,'noise')} · ${p.walk} min walk</small></div><a href="${url(p)}">View spot →</a>${btn('unpin','','x','iconbtn','aria-label="Close map selection"')}</div>`:''}</div><div class="maplegend">${Object.entries(types).map(([t,v])=>`<span><i class="swatch" style="--type-color:${v[1]}"></i>${t}</span>`).join('')}</div><div class="maphint">${icon('info',13)}Select a pin to explore a spot.</div></div>`;mapTransform()}
