function renderCompare(){const list=state.compare.map(find).filter(Boolean);if(!list.length){$('#comparison').innerHTML=empty('Build your comparison','Choose up to three spots to check walking times, conditions, hours, and amenities together.','choose','Choose spots','compare');return}const row=(label,fn)=>`<tr><th scope="row">${label}</th>${list.map(s=>`<td>${fn(s)}</td>`).join('')}</tr>`;$('#comparison').innerHTML=`<div class="results-head"><h2>Side by side <span class="count">${list.length} / 3</span></h2>${btn('choose','Choose spots','compare')}</div><div class="compare-scroll" tabindex="0" role="region" aria-label="Spot comparison, scroll horizontally on small screens"><table class="compare-table"><thead><tr><th scope="col">Study spots</th>${list.map(s=>`<th scope="col"><img class="compare-img" src="assets/${s.image}.jpg" alt="${s.alt}"><a href="${url(s)}">${s.name}</a>${btn('compare','Remove','','textbtn',`data-id="${s.id}" aria-label="Remove ${s.name} from comparison"`)}</th>`).join('')}</tr></thead><tbody>${row('From Campus Gate',s=>s.walk+' min walk · '+s.distance+' m')}${row('Crowd',s=>condition(s,'crowd'))}${row('Noise',s=>condition(s,'noise'))}${row('Availability',status)}${row('Daily hours',hours)}${row('Location',s=>s.building+' · '+s.floor)}${row('Amenities',s=>s.features.join(' · '))}${row('Accessibility',s=>s.access)}${row('Latest reports',s=>'Noise: '+stamp(s,'noise')+'<br>Crowd: '+stamp(s,'crowd'))}</tbody></table></div>`}
