function detail(s){const saved=state.saved.includes(s.id),cmp=state.compare.includes(s.id);showDialog('detail',`<div class="detail"><div class="detail-cover"><img class="detail-img" src="assets/${s.image}.jpg" alt="${s.alt}">${badge(s)}${closeBtn()}</div><div class="modal-inner"><h2 id="dialogTitle">${s.name}</h2><div class="location">${icon('pin',14)}${s.building} · ${s.floor}</div><div class="detail-actions">${btn('save',saved?'Saved':'Save spot','bookmark','control '+(saved?'active':''),`data-id="${s.id}" aria-pressed="${saved}"`)}${btn('compare',cmp?'Added to compare':'Add to compare','compare','control '+(cmp?'active':''),`data-id="${s.id}" aria-pressed="${cmp}"`)}</div><p>${s.desc}</p><div class="detailspec"><div>${status(s)}<small>Daily: ${hours(s)}</small></div><div><strong>${icon('walk',14)} ${s.walk} min walk · ${s.distance} m</strong><small>From Campus Gate</small></div></div><h3>Amenities</h3><div class="amenities">${s.features.map(a=>`<span>${icon(amenIcon[amenities.indexOf(a)],14)}${a}</span>`).join('')}</div><h3>Accessibility</h3><p>${s.access}</p><div class="reportbox"><h3>Report conditions</h3><p>Student-submitted. Tap a level to update it on this device. Initial values are sample reports.</p>${printReport(s,'crowd')}${printReport(s,'noise')}<div class="notice" id="reportNotice" role="status"></div></div>${btn('flag','Flag incorrect information','flag','textbtn',`data-id="${s.id}"`)}</div></div>`)}
