function filtersDialog(){const f=state.filters;showDialog('filters',shell('SPOT DIRECTORY','Filter spots',`<form id="filterForm"><div class="grid2">${field('building','Building',[...new Set(spots.map(s=>s.building))].sort(),f.building,'All buildings')}${field('type','Spot type',Object.keys(types),f.type,'All types')}${field('noise','Noise level',noises,f.noise,'Any noise level')}${field('crowd','Crowd level',crowds,f.crowd,'Any crowd level')}</div><fieldset><legend>Required amenities</legend>${checks('features',amenities,f.features)}</fieldset><label class="check"><input name="open" type="checkbox" ${f.open?'checked':''}>Open at the sample time (Tuesday, 2 PM)</label><div class="actions">${btn('form-reset','Reset filters','','textbtn')}<button class="primary">Apply filters ${icon('arrow',16)}</button></div></form>`))}
function matchForm(){const f=state.rec;showDialog('match',shell('PERSONAL SPOT FINDER','Find me a spot',`<p class="smallcopy">Tell us what you need. We’ll match your must-haves first, then look for the noise and crowd levels you prefer.</p><form id="matchForm"><div class="grid2">${field('noise','Preferred noise level',noises,f.noise,'No preference')}${field('crowd','Preferred crowd level',crowds,f.crowd,'No preference')}</div><label class="field"><span>Maximum walk from Campus Gate</span><select name="walk">${[['','Any distance'],['3','3 minutes'],['5','5 minutes'],['10','10 minutes']].map(([v,l])=>`<option value="${v}" ${f.walk===v?'selected':''}>${l}</option>`).join('')}</select></label><fieldset><legend>Must-have amenities</legend>${checks('features',amenities,f.features)}</fieldset><label class="check"><input type="checkbox" name="open" ${f.open?'checked':''}>Only spots open in the 2 PM sample</label><div class="actions"><button class="primary">${icon('spark',16)}Find my match</button></div></form>`))}
function recommend(f){const matches=spots.filter(s=>(!f.open||openSpot(s))&&(!f.walk||s.walk<=Number(f.walk))&&f.features.every(a=>s.features.includes(a)));const score=s=>(f.noise?2-Math.abs(noises.indexOf(condition(s,'noise'))-noises.indexOf(f.noise)):0)+(f.crowd?2-Math.abs(crowds.indexOf(condition(s,'crowd'))-crowds.indexOf(f.crowd)):0);matches.sort((a,b)=>score(b)-score(a)||a.walk-b.walk);const s=matches[0];if(!s){showDialog('recommend',shell('PERSONAL SPOT FINDER','No exact match yet',`<p>No sample spots meet all your must-haves. Try a longer walk or fewer required amenities.</p>${btn('match','Adjust preferences','filter','primary')}`));return}const reason=[f.noise?(f.noise===condition(s,'noise')?'Matches your '+f.noise.toLowerCase()+' noise preference.':'Closest available noise match: '+condition(s,'noise')+'.'):'',f.crowd?(f.crowd===condition(s,'crowd')?'Matches your crowd preference.':'Current crowd: '+condition(s,'crowd')+'.'):'',f.features.length?'Includes '+f.features.join(', ')+'.':'',f.open?'Open at the 2 PM sample time.':''].filter(Boolean).join(' ');showDialog('recommend',shell('PERSONAL SPOT FINDER','Your best match',`<div class="recommend"><img class="rec-img" src="assets/${s.image}.jpg" alt="${s.alt}"><h3>${s.name}</h3><div class="location">${icon('walk',14)}${s.walk} min walk · ${s.building}</div>${chips(s)}<p>${reason||'The nearest spot that meets your requirements.'}</p></div><div class="actions">${btn('match','Edit preferences','','textbtn')}${btn('detail','View spot','arrow','primary',`data-id="${s.id}"`)}</div>`))}
function choose(){showDialog('choose',shell('SIDE BY SIDE','Choose spots',`<p class="smallcopy">Select up to three spaces for your comparison.</p><form id="chooseForm"><div class="checks">${spots.map(s=>`<label class="check"><input name="spots" type="checkbox" value="${s.id}" ${state.compare.includes(s.id)?'checked':''}>${s.name}</label>`).join('')}</div><p role="alert" id="formError" class="errorMsg"></p><div class="actions"><button class="primary">Show comparison</button></div></form>`))}
function suggest(mode='suggest',id=''){showDialog('suggest',shell('CAMPUS FEEDBACK',mode==='flag'?'Flag spot information':'Suggest or flag a spot',`<p class="note">Demo form: feedback is saved on this device. It is not sent to campus staff.</p><form id="suggestForm">${field('mode','Report type',['Suggest a new spot','Flag incorrect information'],mode==='flag'?'Flag incorrect information':'Suggest a new spot')}<div id="suggestFields"></div><label class="field"><span>Details</span><textarea name="details" required minlength="10" maxlength="800" placeholder="What should someone studying here know? (10 characters minimum)"></textarea></label><p class="errorMsg" id="formError" role="alert"></p><div class="actions"><button class="primary">Save feedback ${icon('arrow',15)}</button></div></form>`));suggestFields(mode,id)}
function suggestFields(mode,id){$('#suggestFields').innerHTML=mode==='flag'?`<label class="field"><span>Which spot?</span><select name="spot" required><option value="">Choose a spot</option>${spots.map(s=>`<option value="${s.id}" ${s.id===id?'selected':''}>${s.name}</option>`).join('')}</select></label>`:`<label class="field"><span>Spot name</span><input name="name" required minlength="2" maxlength="80" placeholder="e.g. East Hall reading room"></label><label class="field"><span>Building or location</span><input name="location" required minlength="2" maxlength="100" placeholder="e.g. East Hall, level 1"></label>`}
function about(){showDialog('about',shell('ABOUT THE DEMO','A campus you can explore',`<p>Northfield University is fictional. The map, AI-generated photos, walking estimates, opening hours, and starting conditions illustrate a sample campus.</p><p>“Open now” uses a fixed Tuesday at 2 PM. Walks start at Campus Gate (the blue dot), not your device location.</p><p>Bookmarks, comparisons, preferences, feedback, and new student reports stay in this browser. Reports use your device’s actual submission time and are not shared with other students.</p>${btn('close','Got it','check','primary')}`))}
function route(){if(!campus)return;let [to,id]=location.hash.slice(1).split('/');let next=['saved','compare'].includes(to)?to:'explore';if(next!==page){selectedPin='';window.scrollTo(0,0)}page=next;$('#nav').classList.remove('open');$('#menu').setAttribute('aria-expanded','false');$('#menu').setAttribute('aria-label','Open menu');if($('#dialog').open)$('#dialog').close();dialogType='';render();if(id&&find(id))detail(find(id))}
