function shiftFocus(selector){document.querySelector(selector)?.focus({preventScroll:true})}
document.addEventListener('click',e=>{let a=e.target.closest('button');if(!a){const navLink=e.target.closest('[data-nav]');if(navLink&&navLink.dataset.nav===page){document.querySelector('#nav').classList.remove('open');document.querySelector('#menu').setAttribute('aria-expanded','false');document.querySelector('#menu').setAttribute('aria-label','Open menu')}return}let act=a.dataset.act,id=a.dataset.id,s=find(id);if(a.id==='menu'){let v=$('#nav').classList.toggle('open');a.setAttribute('aria-expanded',v);a.setAttribute('aria-label',v?'Close menu':'Open menu');return}if(a.dataset.view){state.view=a.dataset.view;persist();render();shiftFocus(`[data-view="${a.dataset.view}"]`);return}if(a.dataset.pin){selectedPin=selectedPin===a.dataset.pin?'':a.dataset.pin;renderMap(filtered());shiftFocus(`[data-pin="${a.dataset.pin}"]`);return}switch(act){
case 'close':closeDialog();break;case 'explore':explorer();break;case 'filters':filtersDialog();break;case 'match':matchForm();break;case 'choose':choose();break;case 'about':about();break;case 'suggest':suggest();break;case 'flag':suggest('flag',id);break;case 'detail':closeDialog();location.hash=page+'/'+id;break;case 'retry':loadData();break;
case 'save':case 'compare':{const key=act==='save'?'saved':'compare',set=state[key],on=set.includes(id),d=dialogType==='detail';if(!s)return;if(!on&&key==='compare'&&set.length>=3){toast('Comparison is full. Remove a spot to add another.');say('Three-spot limit reached.');if(d){let note=$('#reportNotice');note.textContent='Comparison is full. Remove a spot from Compare first.';note.scrollIntoView({block:'nearest'})}return}state[key]=on?set.filter(x=>x!==id):[...set,id];notifyLocal(act==='save'?(on?'Removed from saved spots.':'Spot saved.'):(on?'Removed from comparison.':'Added to comparison.'));render();if(d){a.setAttribute('aria-pressed',String(!on));a.classList.toggle('active',!on);a.innerHTML=icon(act==='save'?'bookmark':'compare',16)+(act==='save'?(on?'Save spot':'Saved'):(on?'Add to compare':'Added to compare'))}else{shiftFocus(`[data-act="${act}"][data-id="${id}"]`)}break}
case 'open':state.filters.open=!state.filters.open;persist();render();shiftFocus('[data-act="open"]');break;
case 'clear':state.filters=structuredClone(defaults);persist();render();$('#search').focus({preventScroll:true});break;
case 'form-reset':$('#filterForm').querySelectorAll('select').forEach(s=>s.value='');$('#filterForm').querySelectorAll('input').forEach(i=>i.checked=false);break;
case 'report':{const k=a.dataset.kind,v=a.dataset.value;if(!s||!['noise','crowd'].includes(k)||!(k==='noise'?noises:crowds).includes(v))return;state.reports[id]={...state.reports[id],[k]:{value:v,at:Date.now()}};const ok=persist();render();$(`[data-line="${k}"]`).outerHTML=printReport(s,k);$('#reportNotice').textContent=ok?'Thanks! Your '+k+' report was saved on this device.':'Report updated for this session; device storage is unavailable.';shiftFocus(`[data-kind="${k}"][data-value="${v}"]`);break}
case 'zoom-in':case 'zoom-out':zoom=Math.max(1,Math.min(2,zoom+(act==='zoom-in'?.25:-.25)));renderMap(filtered());shiftFocus(`[data-act="${act}"]:not(:disabled),.mapstage:only-child`);break;
case 'reset-map':zoom=1;pan=[0,0];selectedPin='';renderMap(filtered());shiftFocus('[data-act="reset-map"]');break;
case 'unpin':{let was=selectedPin;selectedPin='';renderMap(filtered());shiftFocus(`[data-pin="${was}"]`);break}
}})
document.addEventListener('input',e=>{if(e.target.id==='search'){state.filters.q=e.target.value.slice(0,120);persist();render()}});
document.addEventListener('change',e=>{const t=e.target;if(t.dataset.filter){const k=t.dataset.filter;state.filters[k]=t.value;persist();render();shiftFocus(`[data-filter="${k}"]`)}else if(t.id==='sort'){state.sort=t.value;persist();render()}else if(t.name==='mode')suggestFields(t.value.startsWith('Flag')?'flag':'suggest','')});
document.addEventListener('submit',e=>{e.preventDefault();const f=e.target,d=new FormData(f);if(f.id==='filterForm'){state.filters={...state.filters,...Object.fromEntries(['building','type','noise','crowd'].map(k=>[k,d.get(k)])),features:d.getAll('features'),open:d.has('open')};persist();closeDialog();render();return}
if(f.id==='matchForm'){state.rec={noise:d.get('noise'),crowd:d.get('crowd'),walk:d.get('walk'),features:d.getAll('features'),open:d.has('open')};persist();recommend(state.rec);return}
if(f.id==='chooseForm'){let picks=d.getAll('spots');if(picks.length<1||picks.length>3){$('#formError').textContent='Choose between one and three spots.';return}state.compare=picks;persist();closeDialog();render();return}
if(f.id==='suggestForm'){let record=Object.fromEntries([...d].map(([k,v])=>[k,v.trim()]));if((record.name!==undefined&&record.name.length<2)||(record.location!==undefined&&record.location.length<2)||record.details.length<10){$('#formError').textContent='Enter a name and location of at least 2 characters for a new spot, and at least 10 characters of detail.';return}state.suggestions.push({...record,at:Date.now()});const ok=persist();showDialog('success',shell('CAMPUS FEEDBACK',ok?'Feedback saved':'Feedback recorded for this session',`<p>${ok?'Your feedback is saved on this device.':'Device storage is unavailable, so this feedback will be lost on refresh.'} This demo does not send submissions to campus staff.</p>${btn('close','Done','check','primary')}`))}});
$('#dialog').addEventListener('cancel',e=>{e.preventDefault();closeDialog()});$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog()}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('#nav').classList.contains('open'))$('#menu').click();if(e.target.matches('.mapstage')&&zoom>1&&e.key.startsWith('Arrow')){e.preventDefault();const d={ArrowLeft:[28,0],ArrowRight:[-28,0],ArrowUp:[0,28],ArrowDown:[0,-28]}[e.key];if(d){pan=pan.map((p,i)=>p+d[i]);mapTransform()}}});
let drag=null;document.addEventListener('pointerdown',e=>{let st=e.target.closest('.mapstage');if(!st||zoom<=1||e.target.closest('button,a'))return;drag=[e.clientX,e.clientY,...pan];st.setPointerCapture(e.pointerId)});document.addEventListener('pointermove',e=>{if(drag){pan=[drag[2]+e.clientX-drag[0],drag[3]+e.clientY-drag[1]];mapTransform()}});['pointerup','pointercancel'].forEach(k=>document.addEventListener(k,()=>drag=null));
function loadData(){campus=null;spots=[];$('#dataState').hidden=false;$('#dataState').innerHTML='<div class="loader"></div>Loading campus spots…';$('#resultsArea').hidden=true;$('#filters').hidden=true;$$('[data-act="match"],[data-act="suggest"]').forEach(b=>b.disabled=true);if(loadScript)loadScript.remove();window.STUDY_CAMPUS=null;const sc=document.createElement('script');sc.src='data.js';loadScript=sc;
function fail(){campus=null;$('#dataState').innerHTML=empty('The campus guide couldn’t load','Check that data.js is available, then try loading the sample campus again.','retry','Retry loading','info')}
sc.onerror=fail;sc.onload=()=>{try{const data=window.STUDY_CAMPUS;if(!Array.isArray(data?.spots)||!data.spots.length||data.spots.some(s=>!types[s.type]||!s.id||!Array.isArray(s.pos)||!Array.isArray(s.hours)||!Array.isArray(s.features)))throw Error();campus=data;spots=data.spots;state.saved=state.saved.filter(find);state.compare=state.compare.filter(find);$('#dataState').hidden=true;$$('[data-act="match"],[data-act="suggest"]').forEach(b=>b.disabled=false);route();if(unavailable)toast('Browser storage could not be read. Using session defaults.')}catch{fail()}};document.head.append(sc)}
binds();window.addEventListener('hashchange',route);matchMedia('(max-width:700px)').addEventListener('change',()=>render());loadData();

